import * as entryActions from '@/actions/App/Http/Controllers/EntryController';
import * as groupActions from '@/actions/App/Http/Controllers/GroupController';
import * as sessionActions from '@/actions/App/Http/Controllers/AuthenticatedSessionController';
import * as userActions from '@/actions/App/Http/Controllers/UserController';
import { home } from '@/routes';

/**
 * A single place to read route URLs. Everything here is generated by Laravel
 * Wayfinder, so renaming or moving a backend route is a compile error instead
 * of a broken link.
 */
export const routes = {
    home: home.url(),
    entries: {
        index: entryActions.index.url(),
        create: entryActions.create.url(),
        store: entryActions.store.url(),
        show: (id: string) => entryActions.show.url(id),
        edit: (id: string) => entryActions.edit.url(id),
        update: (id: string) => entryActions.update.url(id),
        destroy: (id: string) => entryActions.destroy.url(id),
    },
    groups: {
        index: groupActions.index.url(),
        create: groupActions.create.url(),
        store: groupActions.store.url(),
        show: (id: string) => groupActions.show.url(id),
        edit: (id: string) => groupActions.edit.url(id),
        update: (id: string) => groupActions.update.url(id),
        destroy: (id: string) => groupActions.destroy.url(id),
    },
    auth: {
        login: sessionActions.create.url(),
        loginStore: sessionActions.store.url(),
        signup: userActions.create.url(),
        signupStore: userActions.store.url(),
    },
} as const;

/**
 * Password recovery is not implemented on the backend yet. Keeping the paths
 * here documents the routes the frontend needs.
 */
export const pendingRoutes = {
    logout: '/logout',
    forgotPassword: '/forgot-password',
    resetPassword: '/reset-password',
} as const;
